INSERT INTO public.categories (name, slug, description, image, product_count, featured, sort_order) VALUES
('Sculptural Baskets','sculpture','Wild-fringed statement forms woven as living sculpture.','/__l5e/assets-v1/c9b30099-29a0-4b71-864e-c7f30d51aae5/bolga-hero.jpg',3,true,1),
('Lampshades','lampshade','Hand-coiled pendant shades that filter light into pattern.','/__l5e/assets-v1/4d820abd-023e-46e1-b068-2d5ba0f1ed77/product-lampshade.jpg',2,true,2),
('Woven Fans','fans','Leather-trimmed hand fans in natural dye palettes.','/__l5e/assets-v1/79683c8d-0da3-4ebf-88bd-cea7436f1f02/product-fan.jpg',2,true,3),
('Storage Baskets','storage','Deep, sturdy baskets for blankets, firewood and market days.','/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg',3,true,4),
('Planters','planter','Grass planters that soften architectural greenery.','/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg',2,false,5),
('Market Totes','tote','Leather-handled shoppers built for a lifetime of errands.','/__l5e/assets-v1/80686690-31c5-4272-b939-6b9c46601886/tote.jpg',1,true,6),
('Pet Beds','pet-bed','Round woven nests with washable cushions.','/__l5e/assets-v1/f1e7e7d6-a0fb-4a9a-a86b-af6c069e390c/petbed.jpg',1,false,7);
INSERT INTO public.products (name, slug, sku, category, price, sale_price, stock_quantity, low_stock_threshold, status, featured, primary_image, images, description, dimensions, artisan_story, care_instructions, color, tags, rating, review_count, weight_kg, capacity, handle) VALUES
('Zebra Fringe Sculpture Basket','zebra-fringe-sculpture-basket','VS-SCU-001','sculpture',245,198,4,3,'active',true,'/__l5e/assets-v1/c9b30099-29a0-4b71-864e-c7f30d51aae5/bolga-hero.jpg',ARRAY['/__l5e/assets-v1/c9b30099-29a0-4b71-864e-c7f30d51aae5/bolga-hero.jpg','/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg'],'A monumental collector piece: charcoal and natural straw stripes rise into an untrimmed fringe crown, each strand left wild by the weaver as a signature.','48cm H x 52cm W','Woven over eleven days by Ayamga Atinga of the Sumbrungu cooperative, who learned the wild-fringe finish from her grandmother.','Mist lightly with warm water and reshape by hand. Keep out of direct sun.',ARRAY['Charcoal','Natural Straw'],ARRAY['statement','collector','fringe'],4.9,3,1.80,'Decorative','None'),
('Sahel Vase Sculpture','sahel-vase-sculpture','VS-SCU-002','sculpture',210,NULL,6,3,'active',true,'/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg',ARRAY['/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg','/__l5e/assets-v1/c9b30099-29a0-4b71-864e-c7f30d51aae5/bolga-hero.jpg'],'An hourglass silhouette in banded charcoal, finished with a soft grass plume that catches afternoon light.','44cm H x 34cm W','Shaped on the knee without a mould — the waist is judged entirely by eye.',ARRAY['Mist with warm water, reshape, air dry away from heat.']::text[][1],ARRAY['Charcoal','Natural Straw'],ARRAY['sculpture','plume'],4.8,1,1.40,'Decorative','None'),
('Dusk Plume Vessel','dusk-plume-vessel','VS-SCU-003','sculpture',165,139,2,3,'active',false,'/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg',ARRAY['/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg'],'A smaller sculptural vessel for console tables and shelves, with a low charcoal band and open plume.','32cm H x 26cm W','Woven by the youngest weavers of the cooperative as their mastery piece.','Spray, reshape, dry naturally.',ARRAY['Natural Straw','Charcoal'],ARRAY['sale','small-space'],4.6,0,0.90,'Decorative','None'),
('Savannah Pendant Lampshade','savannah-pendant-lampshade','VS-LMP-001','lampshade',185,NULL,9,3,'active',true,'/__l5e/assets-v1/4d820abd-023e-46e1-b068-2d5ba0f1ed77/product-lampshade.jpg',ARRAY['/__l5e/assets-v1/4d820abd-023e-46e1-b068-2d5ba0f1ed77/product-lampshade.jpg'],'A bell-form pendant in ochre, terracotta and charcoal bands that throws warm woven shadow across a room.','40cm H x 36cm dia','Dyed with roots and bark gathered at the end of the dry season.','Dust with a dry brush. Use LED bulbs only.',ARRAY['Ochre','Terracotta','Natural Straw'],ARRAY['lighting','bestseller'],4.9,2,1.10,'E27 fitting','Cord mount'),
('Harmattan Dome Shade','harmattan-dome-shade','VS-LMP-002','lampshade',149,119,5,3,'active',false,'/__l5e/assets-v1/4d820abd-023e-46e1-b068-2d5ba0f1ed77/product-lampshade.jpg',ARRAY['/__l5e/assets-v1/4d820abd-023e-46e1-b068-2d5ba0f1ed77/product-lampshade.jpg'],'A wide, shallow dome in natural straw with a single indigo band — ideal above a dining table.','26cm H x 45cm dia','Coiled flat then lifted into shape over a clay former.','Dust with a dry brush. Use LED bulbs only.',ARRAY['Natural Straw','Indigo'],ARRAY['lighting','sale'],4.7,0,0.95,'E27 fitting','Cord mount'),
('Terracotta Sunburst Fan','terracotta-sunburst-fan','VS-FAN-001','fans',68,NULL,18,4,'active',true,'/__l5e/assets-v1/79683c8d-0da3-4ebf-88bd-cea7436f1f02/product-fan.jpg',ARRAY['/__l5e/assets-v1/79683c8d-0da3-4ebf-88bd-cea7436f1f02/product-fan.jpg'],'A hand fan with a radiating terracotta sunburst, bound in vegetable-tanned leather and finished with a looped handle.','42cm H x 38cm W','Trimmed by leather workers in Bolgatanga market, a craft passed down father to son.','Wipe leather with a dry cloth. Mist grass to refresh.',ARRAY['Terracotta','Natural Straw'],ARRAY['fan','leather','gift'],4.8,1,0.30,'Wall or hand','Wrapped leather'),
('Indigo Ray Fan','indigo-ray-fan','VS-FAN-002','fans',58,46,12,4,'active',false,'/__l5e/assets-v1/79683c8d-0da3-4ebf-88bd-cea7436f1f02/product-fan.jpg',ARRAY['/__l5e/assets-v1/79683c8d-0da3-4ebf-88bd-cea7436f1f02/product-fan.jpg'],'Indigo rays over pale straw, leather bound. Beautiful in a gallery wall of three.','40cm H x 36cm W','Indigo vats are shared between families and topped up for generations.','Wipe leather with a dry cloth. Mist grass to refresh.',ARRAY['Indigo','Natural Straw'],ARRAY['fan','sale'],4.5,0,0.28,'Wall or hand','Wrapped leather'),
('Midnight Stripe Storage Basket','midnight-stripe-storage-basket','VS-STO-001','storage',158,NULL,11,3,'active',true,'/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg',ARRAY['/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg'],'A deep U-shopper in indigo and straw stripes with double leather handles — blankets, firewood, laundry, market hauls.','38cm H x 46cm W','Handles are stitched with waxed thread so they carry 15kg without stretching.','Mist and reshape if folded in transit. Spot clean only.',ARRAY['Indigo','Natural Straw'],ARRAY['storage','bestseller','leather'],4.9,2,1.60,'45 litres','Double leather'),
('Forest Band Storage Basket','forest-band-storage-basket','VS-STO-002','storage',142,NULL,7,3,'active',false,'/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg',ARRAY['/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg'],'A calm forest-green band across natural straw, with a rolled rim that holds its shape.','36cm H x 42cm W','Green dye is built up over three dips to reach this depth.','Mist and reshape. Keep dry.',ARRAY['Forest','Natural Straw'],ARRAY['storage'],4.6,0,1.50,'38 litres','Double leather'),
('Ochre Nesting Pair','ochre-nesting-pair','VS-STO-003','storage',196,168,3,3,'active',true,'/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg',ARRAY['/__l5e/assets-v1/f9dcf4cf-248f-49c2-87cd-ea4e34f43ff8/product-storage.jpg','/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg'],'Two baskets that nest together, in ochre and straw. Sold as a pair.','40cm and 32cm H','A pair is woven by two sisters working side by side.','Mist and reshape. Keep dry.',ARRAY['Ochre','Natural Straw'],ARRAY['storage','set','sale'],4.8,0,2.60,'50 and 30 litres','Double leather'),
('Sage Band Grass Planter','sage-band-grass-planter','VS-PLA-001','planter',124,NULL,8,3,'active',true,'/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg',ARRAY['/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg'],'A straight-sided planter with a deep sage band, sized for a mature fiddle leaf or bird of paradise.','42cm H x 38cm dia','Woven tightly enough to hold a liner without sagging.','Use a plastic liner. Never water through the grass.',ARRAY['Forest','Natural Straw'],ARRAY['planter','interior'],4.7,1,1.20,'Fits 30cm pot','None'),
('Straw Column Planter','straw-column-planter','VS-PLA-002','planter',98,79,6,3,'active',false,'/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg',ARRAY['/__l5e/assets-v1/65112f8b-4362-4647-8eb7-bed67bf77406/planter.jpg'],'An undyed column planter, all natural straw, for a quieter corner.','36cm H x 30cm dia','Undyed grass shows the true colour of the harvest.','Use a plastic liner. Never water through the grass.',ARRAY['Natural Straw'],ARRAY['planter','sale'],4.4,0,1.00,'Fits 24cm pot','None'),
('Golden Check Market Tote','golden-check-market-tote','VS-TOT-001','tote',132,NULL,14,4,'active',true,'/__l5e/assets-v1/80686690-31c5-4272-b939-6b9c46601886/tote.jpg',ARRAY['/__l5e/assets-v1/80686690-31c5-4272-b939-6b9c46601886/tote.jpg'],'A golden ochre check shopper with tall rolled leather handles that soften with use.','34cm H x 40cm W','Checks are counted, never drawn — the weaver keeps the grid in her head.','Mist and reshape. Condition leather twice a year.',ARRAY['Ochre','Natural Straw'],ARRAY['tote','leather','bestseller'],4.9,1,0.85,'28 litres','Rolled leather'),
('Charcoal Stripe Pet Nest','charcoal-stripe-pet-nest','VS-PET-001','pet-bed',118,NULL,5,3,'active',false,'/__l5e/assets-v1/f1e7e7d6-a0fb-4a9a-a86b-af6c069e390c/petbed.jpg',ARRAY['/__l5e/assets-v1/f1e7e7d6-a0fb-4a9a-a86b-af6c069e390c/petbed.jpg'],'A low round nest in charcoal stripes with a washable cotton cushion. Cats claim it within the hour.','18cm H x 60cm dia','Woven with a doubled base so it survives enthusiastic kneading.','Cushion machine washable at 30C. Mist the grass to reshape.',ARRAY['Charcoal','Natural Straw'],ARRAY['pet','cushion'],4.8,0,1.30,'Up to 8kg pet','None'),
('Harvest Fringe Study','harvest-fringe-study','VS-SCU-004','sculpture',275,NULL,2,3,'draft',false,'/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg',ARRAY['/__l5e/assets-v1/a81bddfd-e0c5-4410-b161-26cb04573b5a/product-sculpture.jpg'],'An unreleased study piece from the 2026 harvest collection.','52cm H x 50cm W','Prototype woven during the studio residency.','Mist and reshape.',ARRAY['Charcoal','Natural Straw'],ARRAY['archive'],0,0,1.90,'Decorative','None');
