INSERT INTO public.journal (title, slug, excerpt, content, cover_image, author, read_time, published_at, tags) VALUES
('How a Bolga basket is born','how-a-bolga-basket-is-born','From the harmattan harvest of veta vera grass to the leather-bound rim, a basket passes through five sets of hands.','Elephant grass — veta vera — is cut at the end of the rainy season, split by thumbnail, twisted into cord and left to dry in the sun. Dye pots are set with roots, bark and indigo, and the cord is dipped in batches so each colour carries the season it was made in.
